  Variables (lo sb ARI c nf : Z).
  Let R := ARI + REGIONINFO_SIZE * c.
  Hypothesis MI : mem_inv bsegs m.
  Hypothesis ST : stk bsegs m lo (bv_unsigned sp).
  Hypothesis LO : aceil <= lo.  Hypothesis HI : lo + 80 <= bv_unsigned sp.
  Hypothesis Ha0 : a0 = wz AINST. Hypothesis Ha2 : a2 = wz c. Hypothesis Ha3 : a3 = wz 0.
  Hypothesis CR : 1 <= c < kNumClasses. Hypothesis NFR : 0 <= nf < 2^64.
  Hypothesis ARIR : AHI_LO <= ARI /\ ARI + 4096 <= aceil /\ ARI mod 4096 = 0.
  Hypothesis IRI : rw_cells bsegs m (AINST + 48) [C8 (wz ARI)].
  Hypothesis ISB : rw_cells bsegs m (AINST + 32) [C8 (wz sb); C4 (wz 0xffffffff); C4 (wz 0)].   (* [comment removed for export] *)
  Hypothesis GOT : rw_cells bsegs m AGOT_LO (map (fun v => C8 (wz v)) AGOT_VALS).
  Hypothesis PSC : rw_cells bsegs m APAGESZ [C8 (wz 4096)].
  Hypothesis RNF : rw_cells bsegs m (R + 16) [C8 (wz nf)].
  (* [comment removed for export] *)
  Hypothesis RS8 : stk bsegs m (R + 80) (R + 96).
